import * as React from "react"
import * as DialogPrimitive from "@radix-ui/react-dialog"
import { X } from "lucide-react"

import { cn } from "@/shared/lib/utils"
import { useIsMobile } from "@/shared/hooks/use-mobile"

const Dialog = DialogPrimitive.Root

const DialogTrigger = DialogPrimitive.Trigger

const DialogPortal = DialogPrimitive.Portal

const DialogClose = DialogPrimitive.Close

const DialogOverlay = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay
    ref={ref}
    // data-mia-overlay marker para CSS global que recolhe overlay quando
    // MIA pane está aberto (não cobre a área do chat MIA).
    data-mia-overlay="true"
    className={cn(
      "fixed inset-0 z-50 bg-black/80  data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",
      className
    )}
    {...props}
  />
))
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName

const DialogContent = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>
>(({ className, children, onPointerDownOutside, onInteractOutside, onEscapeKeyDown, ...props }, ref) => {
  const isMobile = useIsMobile()

  // GLOBAL MIA MODAL PROTECTION
  // Se este Dialog tem data-mia-modal E MIA está atuando (data-mia-pane-open
  // no html + alguma execution flag), bloqueia close em click fora.
  // Sem isso, click no chat MIA pode fechar modais que ela acabou de abrir.
  const hasMiaModalTag = !!(props as any)['data-mia-modal']
  const safeBlock = (e: Event, original?: (e: any) => void) => {
    if (hasMiaModalTag && typeof document !== 'undefined' && document.documentElement.hasAttribute('data-mia-pane-open')) {
      e.preventDefault()
      return
    }
    if (original) original(e as any)
  }

  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        ref={ref}
        onPointerDownOutside={(e) => safeBlock(e as unknown as Event, onPointerDownOutside as any)}
        onInteractOutside={(e) => safeBlock(e as unknown as Event, onInteractOutside as any)}
        onEscapeKeyDown={(e) => safeBlock(e as unknown as Event, onEscapeKeyDown as any)}
        className={cn(
          // Base styles
          "fixed z-50 grid gap-4 border bg-background shadow-lg duration-200",
          "data-[state=open]:animate-in data-[state=closed]:animate-out",
          "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0",

          // Mobile-first: fullscreen on mobile for better UX
          isMobile ? [
            // Mobile: fullscreen with safe areas
            "inset-0 w-full h-full max-w-none max-h-none",
            "p-4 pt-safe-top pb-safe-bottom",
            "data-[state=closed]:slide-out-to-bottom data-[state=open]:slide-in-from-bottom",
            "overflow-y-auto"
          ] : [
            // Desktop: centered modal
            "left-[50%] top-[50%] w-full max-w-lg translate-x-[-50%] translate-y-[-50%]",
            "p-6 sm:rounded-lg",
            "data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95",
            "data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%]",
            "data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%]"
          ],
          className
        )}
        {...props}
      >
        {children}
        <DialogPrimitive.Close 
          className={cn(
            "absolute rounded-sm opacity-70 ring-offset-background transition-opacity",
            "hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
            "disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground",
            // Mobile: larger touch target positioned for thumb access
            isMobile ? [
              "right-4 top-4 h-12 w-12 flex items-center justify-center",
              "bg-background/80 backdrop-blur-sm border"
            ] : [
              "right-4 top-4 h-6 w-6 flex items-center justify-center"
            ]
          )}
        >
          <X className={cn(isMobile ? "h-6 w-6" : "h-4 w-4")} />
          <span className="sr-only">Close</span>
        </DialogPrimitive.Close>
      </DialogPrimitive.Content>
    </DialogPortal>
  )
})
DialogContent.displayName = DialogPrimitive.Content.displayName

const DialogHeader = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => {
  const isMobile = useIsMobile()

  return (
    <div
      className={cn(
        "flex flex-col space-y-1.5",
        // Mobile: always left-aligned for better readability
        isMobile ? "text-left" : "text-center sm:text-left",
        // Mobile: extra padding for better touch interaction
        isMobile && "pb-4",
        className
      )}
      {...props}
    />
  )
}
DialogHeader.displayName = "DialogHeader"

const DialogFooter = ({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) => {
  const isMobile = useIsMobile()

  return (
    <div
      className={cn(
        // Mobile: always column layout with proper spacing for touch
        isMobile ? [
          "flex flex-col space-y-3 pt-6",
          // Stick to bottom on mobile for thumb access
          "mt-auto"
        ] : [
          "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2"
        ],
        className
      )}
      {...props}
    />
  )
}
DialogFooter.displayName = "DialogFooter"

const DialogTitle = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Title>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Title>
>(({ className, ...props }, ref) => {
  const isMobile = useIsMobile()

  return (
    <DialogPrimitive.Title
      ref={ref}
      className={cn(
        "font-semibold leading-none tracking-tight",
        // Mobile: larger text for better readability
        isMobile ? "text-xl" : "text-lg",
        className
      )}
      {...props}
    />
  )
})
DialogTitle.displayName = DialogPrimitive.Title.displayName

const DialogDescription = React.forwardRef<
  React.ElementRef<typeof DialogPrimitive.Description>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Description>
>(({ className, ...props }, ref) => {
  const isMobile = useIsMobile()

  return (
    <DialogPrimitive.Description
      ref={ref}
      className={cn(
        "text-muted-foreground",
        // Mobile: larger text for better readability (minimum 16px)
        isMobile ? "text-base" : "text-sm",
        className
      )}
      {...props}
    />
  )
})
DialogDescription.displayName = DialogPrimitive.Description.displayName

export {
  Dialog,
  DialogPortal,
  DialogOverlay,
  DialogClose,
  DialogTrigger,
  DialogContent,
  DialogHeader,
  DialogFooter,
  DialogTitle,
  DialogDescription,
}

