import { render } from '@testing-library/react';
import { describe, it, expect, vi } from 'vitest';

// ── Mocks ──────────────────────────────────────────────────────────────────
vi.mock('react-router-dom', () => ({
    useNavigate: () => vi.fn(),
    useParams: () => ({}),
    useSearchParams: () => [new URLSearchParams(), vi.fn()],
    useLocation: () => ({ pathname: '/', search: '', hash: '', state: null }),
}));

vi.mock('@/shared/contexts/StoreContext', () => ({
    useStore: () => ({
        selectedStore: { id: 1, name: 'Loja Central' },
        stores: [{ id: 1, name: 'Loja Central' }],
    }),
}));

vi.mock('@/integrations/supabase/client', () => {
    const builder: Record<string, any> = {};
    const chainMethods = [
        'from', 'select', 'insert', 'update', 'upsert', 'delete',
        'eq', 'neq', 'gt', 'gte', 'lt', 'lte', 'like', 'ilike',
        'is', 'in', 'not', 'or', 'filter', 'match',
        'order', 'limit', 'range', 'single', 'maybeSingle',
        'csv', 'returns',
    ];
    for (const m of chainMethods) {
        builder[m] = vi.fn().mockReturnValue(builder);
    }
    builder.then = vi.fn((resolve: any) => resolve({ data: [], error: null }));
    return {
        supabase: {
            ...builder,
            rpc: vi.fn().mockResolvedValue({ data: [], error: null }),
            auth: {
                getUser: vi.fn(),
                getSession: vi.fn().mockResolvedValue({ data: { session: null }, error: null }),
                onAuthStateChange: vi.fn(() => ({ data: { subscription: { unsubscribe: vi.fn() } } })),
            },
            channel: vi.fn().mockReturnValue({
                on: vi.fn().mockReturnThis(),
                subscribe: vi.fn(),
            }),
            removeChannel: vi.fn(),
        },
    };
});

vi.mock('@/shared/hooks/use-toast', () => ({
    toast: vi.fn(),
    useToast: () => ({ toast: vi.fn() }),
}));

vi.mock('@/shared/hooks/useAuth', () => ({
    useAuth: () => ({
        user: { id: 'uid-1', user_metadata: { nome: 'Test' }, email: 'test@test.com' },
    }),
}));

vi.mock('@/shared/hooks/usePermissions', () => ({
    usePermissions: () => ({
        hasPermission: () => true,
        canViewFinanceiro: () => true,
        isAdmin: () => true,
    }),
}));

vi.mock('@/shared/hooks/use-mobile', () => ({
    useIsMobile: () => false,
}));

vi.mock('@/shared/hooks/useStore', () => ({
    useStore: () => ({
        selectedStore: { id: 1, name: 'Loja Central' },
        stores: [{ id: 1, name: 'Loja Central' }],
    }),
}));

vi.mock('@/shared/ui/PermissionBlur', () => ({
    PermissionBlur: ({ children }: any) => <>{children}</>,
}));

vi.mock('@/features/financeiro/model/useAccounting', () => ({
    useAccounting: () => ({
        journals: [],
        moves: [],
        summary: { totalBalance: 0, monthInflows: 0, monthOutflows: 0, monthResult: 0, pendingCount: 0 },
        cashBalance: 0,
        isLoading: false,
        movesLoading: false,
        hasMore: false,
        filters: {},
        applyFilters: vi.fn(),
        loadMore: vi.fn(),
        fetchMoveLines: vi.fn().mockResolvedValue([]),
        postMove: vi.fn().mockResolvedValue(undefined),
        refresh: vi.fn(),
    }),
}));

vi.mock('@/features/financeiro/model/useFinancialData', () => ({
    useFinancialData: () => ({
        data: [],
        isLoading: false,
        error: null,
    }),
}));

vi.mock('@/features/financeiro/model/useFinancialAccounts', () => ({
    useFinancialAccounts: () => ({
        transactions: [],
        isLoading: false,
        summary: { totalPayable: 0, totalReceivable: 0, totalOverdue: 0, totalPaidMonth: 0, uncategorizedCount: 0, dateContext: 'Todos os períodos' },
        createTransaction: vi.fn(),
        createTransactionWithInstallments: vi.fn(),
        createAsset: vi.fn(),
        updateStatus: vi.fn(),
        updateTransaction: vi.fn(),
        fetchTransactions: vi.fn(),
        fetchInstallments: vi.fn().mockResolvedValue([]),
        updateInstallmentStatus: vi.fn(),
        page: 0,
        setPage: vi.fn(),
        hasMore: false,
        categories: [],
        costCenters: [],
        finStores: [],
        selectedLojaId: 'all',
        setSelectedLojaId: vi.fn(),
        refresh: vi.fn(),
    }),
}));

vi.mock('@/features/financeiro/model/useCashBook', () => ({
    useCashBook: () => ({
        movements: [],
        balance: 0,
        loading: false,
        refresh: vi.fn(),
    }),
}));

// Mock child components that make direct supabase calls to prevent hangs
vi.mock('@/features/financeiro/ui/FinancialAnalytics', () => ({
    FinancialAnalytics: () => <div data-testid="financial-analytics" />,
}));

vi.mock('@/features/financeiro/ui/FinanceConfig', () => ({
    FinanceConfig: () => <div data-testid="finance-config" />,
}));

vi.mock('@/features/financeiro/ui/DREReport', () => ({
    DREReport: () => <div data-testid="dre-report" />,
}));

vi.mock('@/features/financeiro/ui/BalanceSheetReport', () => ({
    BalanceSheetReport: () => <div data-testid="balance-sheet-report" />,
}));

vi.mock('./LivroCaixa', () => ({
    default: () => <div data-testid="livro-caixa" />,
}));

vi.mock('@/features/financeiro/ui/AccountingDashboard', () => ({
    AccountingDashboard: () => <div data-testid="accounting-dashboard" />,
}));

vi.mock('recharts', () => ({
    ResponsiveContainer: ({ children }: any) => <div>{children}</div>,
    BarChart: () => <div />,
    Bar: () => <div />,
    XAxis: () => <div />,
    YAxis: () => <div />,
    CartesianGrid: () => <div />,
    Tooltip: () => <div />,
    PieChart: () => <div />,
    Pie: () => <div />,
    Cell: () => <div />,
    Legend: () => <div />,
    AreaChart: () => <div />,
    Area: () => <div />,
}));

// ── Tests ──────────────────────────────────────────────────────────────────

describe('Financeiro.page — smoke render', () => {
    it('renders without crashing', async () => {
        const { default: Financeiro } = await import('./Financeiro.page');
        render(<Financeiro />);
        expect(document.body).toBeTruthy();
    }, 15_000);
});

