1	// MIA 2.0 Glass-Box — hook adicional (NÃO modifica useMia.ts existente).
2	//
3	// Provê o estado do "Modo IA" (split-view + computer use) que coexiste com
4	// todo o sistema MIA atual (chat /mia, FAB, MiaInlineChat, MiaMobileSheet).
5	//
6	// Quando miaModeEnabled = ON:
7	//   - DashboardLayout renderiza ResizablePanelGroup com MiaGlassBoxPane à direita
8	//   - useMiaAutoDiscover persiste Page Model da rota atual
9	//   - MIA pode operar UI via MiaDomController (em fases futuras)
10	//
11	// Quando OFF: comportamento atual permanece intacto.
12	//
13	// Doc: docs/mia/ARCHITECTURE.md (Section 9), docs/mia/IMPLEMENTATION.md (Week 2).
14	
15	import { useState, useCallback, useEffect } from 'react';
16	import { setWatchLogSnapshot, pushWatchLogSnapshot, updateWatchLogSnapshotEntry } from '../lib/watchLogSnapshot';
17	import type {
18	  MiaPageModel,
19	  MiaWatchLogEntry,
20	  MiaAutonomyMode,
21	  MiaHighlightTarget,
22	  MiaRecordedAction,
23	} from '@/types/mia';
24	
25	const MIA_MODE_KEY = 'mia_glassbox_mode';
26	const MIA_AUTONOMY_KEY = 'mia_autonomy_mode';
27	const MIA_PANE_SIZE_KEY = 'mia_pane_size';
28	const MIA_WATCHLOG_KEY = 'mia_watchlog';
29	const MIA_RECORDED_KEY = 'mia_recorded_actions';
30	const MIA_PAUSED_INTENT_KEY = 'mia_paused_intent';
31	
32	// ── localStorage helpers ─────────────────────────────────────
33	
34	function loadMiaMode(): boolean {
35	  try { return localStorage.getItem(MIA_MODE_KEY) === '1'; } catch { return false; }
36	}
37	
38	function loadPaneSize(): number {
39	  try {
40	    const saved = localStorage.getItem(MIA_PANE_SIZE_KEY);
41	    const n = saved ? parseInt(saved, 10) : 33;
42	    if (Number.isFinite(n) && n >= 20 && n <= 60) return n;
43	    return 33;
44	  } catch { return 33; }
45	}
46	
47	function loadAutonomy(): MiaAutonomyMode {
48	  try {
49	    const saved = localStorage.getItem(MIA_AUTONOMY_KEY);
50	    if (saved === 'cuidadoso' || saved === 'assistido' || saved === 'live') return saved;
51	    return 'assistido';
52	  } catch { return 'assistido'; }
53	}
54	
55	function loadWatchLog(): MiaWatchLogEntry[] {
56	  try {
57	    const raw = localStorage.getItem(MIA_WATCHLOG_KEY);
58	    if (!raw) return [];
59	    const parsed = JSON.parse(raw);
60	    if (!Array.isArray(parsed)) return [];
61	    // Last entry "in_progress" stale ao recarregar — sanitiza pra 'info'
62	    // pra evitar isExecuting ficar travado em true pós-reload.
63	    return parsed.slice(-200).map((e: any, i: number, arr: any[]) => {
64	      if (i === arr.length - 1 && e.status === 'in_progress') {
65	        return { ...e, status: 'info' as const };
66	      }
67	      return e;
68	    });
69	  } catch { return []; }
70	}
71	
72	function loadRecordedActions(): MiaRecordedAction[] {
73	  try {
74	    const raw = localStorage.getItem(MIA_RECORDED_KEY);
75	    if (!raw) return [];
76	    const parsed = JSON.parse(raw);
77	    return Array.isArray(parsed) ? parsed.slice(-100) : [];
78	  } catch { return []; }
79	}
80	
81	export interface MiaPausedIntent {
82	  originalMessage: string;
83	  pausedAt: string;  // ISO timestamp
84	  lastRoute: string;
85	  lastStore: string | null;
86	  lastModalOpen: string | null;
87	  stepsExecutedSummary: string;
88	}
89	
90	function loadPausedIntent(): MiaPausedIntent | null {
91	  try {
92	    const raw = localStorage.getItem(MIA_PAUSED_INTENT_KEY);
93	    if (!raw) return null;
94	    const parsed = JSON.parse(raw);
95	    return parsed && typeof parsed === 'object' && parsed.originalMessage ? parsed : null;
96	  } catch { return null; }
97	}
98	
99	// ── Tipo público ─────────────────────────────────────────────
100	
101	export interface UseMiaGlassBoxReturn {
102	  /** Modo IA ON/OFF — toggle global do glass-box pane. Persistido em localStorage. */
103	  miaModeEnabled: boolean;
104	  toggleMiaMode: () => void;
105	  setMiaModeEnabled: (enabled: boolean) => void;
106	
107	  /** Largura do pane (% da viewport). 20-60. */
108	  paneSize: number;
109	  setPaneSize: (size: number) => void;
110	
111	  /** Modo de autonomia: cuidadoso / assistido / live. */
112	  autonomyMode: MiaAutonomyMode;
113	  setAutonomyMode: (mode: MiaAutonomyMode) => void;
114	
115	  /** Page Model atual (L3) — auto-descoberto via useMiaAutoDiscover. */
116	  currentPageModel: MiaPageModel | null;
117	  setCurrentPageModel: (model: MiaPageModel | null) => void;
118	
119	  /** Watch log — narração em tempo real do que MIA está fazendo. */
120	  watchLog: MiaWatchLogEntry[];
121	  addWatchLogEntry: (entry: Omit<MiaWatchLogEntry, 'id' | 'timestamp'>) => void;
122	  clearWatchLog: () => void;
123	  /** Renomeia entries órfãs 'in_progress' → 'info' (parado) ao fim do stream. */
124	  finalizeOrphanedEntries: () => void;
125	
126	  /** Elemento sendo destacado na UI (DOM highlight overlay). */
127	  currentHighlight: MiaHighlightTarget | null;
128	  highlightElement: (selector: string, label: string) => void;
129	  clearHighlight: () => void;
130	
131	  /** Posição do cursor avatar MIA (durante execução visual). */
132	  cursorPosition: { x: number; y: number } | null;
133	  moveCursor: (pos: { x: number; y: number } | null) => void;
134	
135	  /** Indica se há execução em andamento (watch log com step in_progress). */
136	  isExecuting: boolean;
137	
138	  /** MIA pausada — usuário clicou Pausar; UI ERP fica liberada. */
139	  isPaused: boolean;
140	  setPaused: (paused: boolean) => void;
141	
142	  /** Intent original armazenado quando user pausou — pra retomada com re-entendimento. */
143	  pausedIntent: MiaPausedIntent | null;
144	  savePausedIntent: (intent: MiaPausedIntent) => void;
145	  clearPausedIntent: () => void;
146	
147	  /** Ações DOM gravadas (estruturadas) pra workflow replay. */
148	  recordedActions: MiaRecordedAction[];
149	  recordAction: (action: Omit<MiaRecordedAction, 'id' | 'timestamp'>) => void;
150	  clearRecordedActions: () => void;
151	}
152	
153	// ── Hook ─────────────────────────────────────────────────────
154	
155	export function useMiaGlassBox(): UseMiaGlassBoxReturn {
156	  const [miaModeEnabled, setMiaModeEnabledState] = useState<boolean>(loadMiaMode);
157	  const [paneSize, setPaneSizeState] = useState<number>(loadPaneSize);
158	  const [autonomyMode, setAutonomyModeState] = useState<MiaAutonomyMode>(loadAutonomy);
159	  const [currentPageModel, setCurrentPageModel] = useState<MiaPageModel | null>(null);
160	  const [watchLog, setWatchLog] = useState<MiaWatchLogEntry[]>(loadWatchLog);
161	  const [currentHighlight, setCurrentHighlight] = useState<MiaHighlightTarget | null>(null);
162	  const [cursorPosition, setCursorPosition] = useState<{ x: number; y: number } | null>(null);
163	  const [recordedActions, setRecordedActions] = useState<MiaRecordedAction[]>(loadRecordedActions);
164	  const [isPaused, setIsPausedState] = useState<boolean>(false);
165	  const [pausedIntent, setPausedIntentState] = useState<MiaPausedIntent | null>(loadPausedIntent);
166	
167	  // Persist watchLog em mudanças (last 200, debounced via effect)
168	  useEffect(() => {
169	    try { localStorage.setItem(MIA_WATCHLOG_KEY, JSON.stringify(watchLog.slice(-200))); } catch { /* noop — quota */ }
170	  }, [watchLog]);
171	
172	  useEffect(() => {
173	    try { localStorage.setItem(MIA_RECORDED_KEY, JSON.stringify(recordedActions.slice(-100))); } catch { /* noop */ }
174	  }, [recordedActions]);
175	
176	  // ── miaModeEnabled persist ─────────────────────────────────
177	
178	  const setMiaModeEnabled = useCallback((enabled: boolean) => {
179	    setMiaModeEnabledState(enabled);
180	    try { localStorage.setItem(MIA_MODE_KEY, enabled ? '1' : '0'); } catch { /* noop */ }
181	  }, []);
182	
183	  const toggleMiaMode = useCallback(() => {
184	    setMiaModeEnabledState(prev => {
185	      const next = !prev;
186	      try { localStorage.setItem(MIA_MODE_KEY, next ? '1' : '0'); } catch { /* noop */ }
187	      return next;
188	    });
189	  }, []);
190	
191	  // ── paneSize persist ───────────────────────────────────────
192	
193	  const setPaneSize = useCallback((size: number) => {
194	    const clamped = Math.max(20, Math.min(60, Math.round(size)));
195	    setPaneSizeState(clamped);
196	    try { localStorage.setItem(MIA_PANE_SIZE_KEY, String(clamped)); } catch { /* noop */ }
197	  }, []);
198	
199	  // ── autonomyMode persist ───────────────────────────────────
200	
201	  const setAutonomyMode = useCallback((mode: MiaAutonomyMode) => {
202	    setAutonomyModeState(mode);
203	    try { localStorage.setItem(MIA_AUTONOMY_KEY, mode); } catch { /* noop */ }
204	  }, []);
205	
206	  // ── watch log ──────────────────────────────────────────────
207	
208	  /**
209	   * Adiciona entry no watch log. Agrupamento inteligente:
210	   * - Se entry.step_id existe E há entry anterior com mesmo step_id E status
211	   *   in_progress, ATUALIZA a entry existente (em vez de adicionar nova).
212	   *   Resultado: spinner some quando step termina (não duplica visualmente).
213	   * - Senão, adiciona normal.
214	   */
215	  const addWatchLogEntry = useCallback((entry: Omit<MiaWatchLogEntry, 'id' | 'timestamp'>) => {
216	    const fullEntry: MiaWatchLogEntry = {
217	      ...entry,
218	      id: typeof crypto !== 'undefined' && 'randomUUID' in crypto
219	        ? crypto.randomUUID()
220	        : `wl-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
221	      timestamp: new Date().toISOString(),
222	    };
223	    setWatchLog(prev => {
224	      // Heurística pra agrupar: msgs com mesma kind (clicando/preenchendo/etc)
225	      // e mesmo "alvo" recebem update in-place quando vira success/error.
226	      // step_id explícito tem prioridade. Sem step_id, usa match por message stem.
227	      const isFinal = entry.status === 'success' || entry.status === 'error' || entry.status === 'warning';
228	      if (isFinal) {
229	        // Procura entry in_progress correspondente (último wins)
230	        const targetIdx = [...prev].reverse().findIndex(e => {
231	          if (e.status !== 'in_progress') return false;
232	          if (entry.step_id && e.step_id === entry.step_id) return true;
233	          // Sem step_id, match por verbo/kind comum:
234	          // "🖱 Clicando: X" → "✓ Clicado: X"
235	          // "⌨ Preenchendo X" → "✓ Preenchido: X"
236	          // "▼ Selecionando X" → "✓ Selecionado: X"
237	          // "→ Navegando" → "✓ Navegado"
238	          const oldMsg = e.message.toLowerCase();
239	          const newMsg = entry.message.toLowerCase();
240	          const pairs = [
241	            ['clicando', 'clicado'], ['clicando', 'click falhou'],
242	            ['preenchendo', 'preenchido'], ['preenchendo', 'type falhou'],
243	            ['selecionando', 'selecionado'], ['selecionando', 'select falhou'],
244	            ['navegando', 'navegado'], ['aguardando', 'apareceu'],
245	            ['trocando loja', 'loja trocada'],
246	          ];
247	          return pairs.some(([open, close]) => oldMsg.includes(open) && newMsg.includes(close));
248	        });
249	        if (targetIdx !== -1) {
250	          // Replace in-place — actual index = length-1 - reversedIdx
251	          const actualIdx = prev.length - 1 - targetIdx;
252	          const next = [...prev];
253	          next[actualIdx] = { ...fullEntry, id: prev[actualIdx].id };  // preserva id pra animation continuity
254	          // Atualiza snapshot ref sync (in-place pelo id preservado)
255	          updateWatchLogSnapshotEntry(prev[actualIdx].id, { ...fullEntry, id: prev[actualIdx].id });
256	          return next;
257	        }
258	      }
259	      const appended = [...prev, fullEntry];
260	      const capped = appended.length > 200 ? appended.slice(-200) : appended;
261	      // Push síncrono pro snapshot ref — evita race no finally do useMia
262	      pushWatchLogSnapshot(fullEntry);
263	      return capped;
264	    });
265	  }, []);
266	
267	  const clearWatchLog = useCallback(() => {
268	    setWatchLog([]);
269	  }, []);
270	
271	  // Finaliza entries "in_progress" órfãs (stream encerrou sem update)
272	  // Renomeia pra status final 'info' + sufixo "(parado)" pra parar o spinner.
273	  // Sem isso, watch log fica girando indefinidamente quando agent termina.
274	  const finalizeOrphanedEntries = useCallback(() => {
275	    setWatchLog(prev => prev.map(e =>
276	      e.status === 'in_progress'
277	        ? { ...e, status: 'info' as const, message: `${e.message} (concluído)` }
278	        : e
279	    ));
280	  }, []);
281	
282	  // ── highlight ──────────────────────────────────────────────
283	
284	  const highlightElement = useCallback((selector: string, label: string) => {
285	    setCurrentHighlight({ selector, label });
286	  }, []);
287	
288	  const clearHighlight = useCallback(() => {
289	    setCurrentHighlight(null);
290	  }, []);
291	
292	  // ── cursor ─────────────────────────────────────────────────
293	
294	  const moveCursor = useCallback((pos: { x: number; y: number } | null) => {
295	    setCursorPosition(pos);
296	  }, []);
297	
298	  // ── recordedActions ────────────────────────────────────────
299	
300	  const recordAction = useCallback((action: Omit<MiaRecordedAction, 'id' | 'timestamp'>) => {
301	    const full: MiaRecordedAction = {
302	      ...action,
303	      id: typeof crypto !== 'undefined' && 'randomUUID' in crypto
304	        ? crypto.randomUUID()
305	        : `ra-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
306	      timestamp: new Date().toISOString(),
307	    };
308	    setRecordedActions(prev => {
309	      const next = [...prev, full];
310	      return next.length > 100 ? next.slice(-100) : next; // cap 100
311	    });
312	  }, []);
313	
314	  const clearRecordedActions = useCallback(() => {
315	    setRecordedActions([]);
316	  }, []);
317	
318	  // ── pause / resume ─────────────────────────────────────────
319	
320	  const setPaused = useCallback((paused: boolean) => {
321	    setIsPausedState(paused);
322	  }, []);
323	
324	  const savePausedIntent = useCallback((intent: MiaPausedIntent) => {
325	    setPausedIntentState(intent);
326	    try { localStorage.setItem(MIA_PAUSED_INTENT_KEY, JSON.stringify(intent)); } catch { /* noop */ }
327	  }, []);
328	
329	  const clearPausedIntent = useCallback(() => {
330	    setPausedIntentState(null);
331	    try { localStorage.removeItem(MIA_PAUSED_INTENT_KEY); } catch { /* noop */ }
332	  }, []);
333	
334	  // ── derived ────────────────────────────────────────────────
335	  // isExecuting baseado SÓ no último entry — antes era .some() que ficava
336	  // stuck em true porque entries antigos "in_progress" não eram atualizados
337	  // (cada ação add 2 entries: 1 in_progress + 1 success, ambos persistem).
338	  const isExecuting = watchLog.length > 0
339	    && watchLog[watchLog.length - 1].status === 'in_progress';
340	
341	  // Snapshot ref pra useMia (hook separado) capturar quando finaliza message.
342	  // Sync (não async) pra estar atualizado quando useMia salvar message.
343	  useEffect(() => {
344	    setWatchLogSnapshot(watchLog);
345	  }, [watchLog]);
346	
347	  return {
348	    miaModeEnabled,
349	    toggleMiaMode,
350	    setMiaModeEnabled,
351	    paneSize,
352	    setPaneSize,
353	    autonomyMode,
354	    setAutonomyMode,
355	    currentPageModel,
356	    setCurrentPageModel,
357	    watchLog,
358	    addWatchLogEntry,
359	    clearWatchLog,
360	    finalizeOrphanedEntries,
361	    currentHighlight,
362	    highlightElement,
363	    clearHighlight,
364	    cursorPosition,
365	    moveCursor,
366	    isExecuting,
367	    recordedActions,
368	    recordAction,
369	    clearRecordedActions,
370	    isPaused,
371	    setPaused,
372	    pausedIntent,
373	    savePausedIntent,
374	    clearPausedIntent,
375	  };
376	}
