//   - DashboardLayout renderiza ResizablePanelGroup com MiaGlassBoxPane à direita
//   - useMiaAutoDiscover persiste Page Model da rota atual
//   - MIA pode operar UI via MiaDomController (em fases futuras)
//
// Quando OFF: comportamento atual permanece intacto.
//
// Doc: docs/mia/ARCHITECTURE.md (Section 9), docs/mia/IMPLEMENTATION.md (Week 2).

import { useState, useCallback, useEffect } from 'react';
import { setWatchLogSnapshot, pushWatchLogSnapshot, updateWatchLogSnapshotEntry } from '../lib/watchLogSnapshot';
import type {
  MiaPageModel,
  MiaWatchLogEntry,
  MiaAutonomyMode,
  MiaHighlightTarget,
  MiaRecordedAction,
} from '@/types/mia';

const MIA_MODE_KEY = 'mia_glassbox_mode';
const MIA_AUTONOMY_KEY = 'mia_autonomy_mode';
const MIA_PANE_SIZE_KEY = 'mia_pane_size';
const MIA_WATCHLOG_KEY = 'mia_watchlog';
const MIA_RECORDED_KEY = 'mia_recorded_actions';
const MIA_PAUSED_INTENT_KEY = 'mia_paused_intent';

// ── localStorage helpers ─────────────────────────────────────

function loadMiaMode(): boolean {
  try { return localStorage.getItem(MIA_MODE_KEY) === '1'; } catch { return false; }
}

function loadPaneSize(): number {
  try {
    const saved = localStorage.getItem(MIA_PANE_SIZE_KEY);
    const n = saved ? parseInt(saved, 10) : 33;
    if (Number.isFinite(n) && n >= 20 && n <= 60) return n;
    return 33;
  } catch { return 33; }
}

function loadAutonomy(): MiaAutonomyMode {
  try {
    const saved = localStorage.getItem(MIA_AUTONOMY_KEY);
    if (saved === 'cuidadoso' || saved === 'assistido' || saved === 'live') return saved;
    return 'assistido';
  } catch { return 'assistido'; }
}

function loadWatchLog(): MiaWatchLogEntry[] {
  try {
    const raw = localStorage.getItem(MIA_WATCHLOG_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    // Last entry "in_progress" stale ao recarregar — sanitiza pra 'info'
    // pra evitar isExecuting ficar travado em true pós-reload.
    return parsed.slice(-200).map((e: any, i: number, arr: any[]) => {
      if (i === arr.length - 1 && e.status === 'in_progress') {
        return { ...e, status: 'info' as const };
      }
      return e;
    });
  } catch { return []; }
}

function loadRecordedActions(): MiaRecordedAction[] {
  try {
    const raw = localStorage.getItem(MIA_RECORDED_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.slice(-100) : [];
  } catch { return []; }
}

export interface MiaPausedIntent {
  originalMessage: string;
  pausedAt: string;  // ISO timestamp
  lastRoute: string;
  lastStore: string | null;
  lastModalOpen: string | null;
  stepsExecutedSummary: string;
}

function loadPausedIntent(): MiaPausedIntent | null {
  try {
    const raw = localStorage.getItem(MIA_PAUSED_INTENT_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && parsed.originalMessage ? parsed : null;
  } catch { return null; }
}

// ── Tipo público ─────────────────────────────────────────────

export interface UseMiaGlassBoxReturn {
  /** Modo IA ON/OFF — toggle global do glass-box pane. Persistido em localStorage. */
  miaModeEnabled: boolean;
  toggleMiaMode: () => void;
  setMiaModeEnabled: (enabled: boolean) => void;

  /** Largura do pane (% da viewport). 20-60. */
  paneSize: number;
  setPaneSize: (size: number) => void;

  /** Modo de autonomia: cuidadoso / assistido / live. */
  autonomyMode: MiaAutonomyMode;
  setAutonomyMode: (mode: MiaAutonomyMode) => void;

  /** Page Model atual (L3) — auto-descoberto via useMiaAutoDiscover. */
  currentPageModel: MiaPageModel | null;
  setCurrentPageModel: (model: MiaPageModel | null) => void;

  /** Watch log — narração em tempo real do que MIA está fazendo. */
  watchLog: MiaWatchLogEntry[];
  addWatchLogEntry: (entry: Omit<MiaWatchLogEntry, 'id' | 'timestamp'>) => void;
  clearWatchLog: () => void;
  /** Renomeia entries órfãs 'in_progress' → 'info' (parado) ao fim do stream. */
  finalizeOrphanedEntries: () => void;

  /** Elemento sendo destacado na UI (DOM highlight overlay). */
  currentHighlight: MiaHighlightTarget | null;
  highlightElement: (selector: string, label: string) => void;
  clearHighlight: () => void;

  /** Posição do cursor avatar MIA (durante execução visual). */
  cursorPosition: { x: number; y: number } | null;
  moveCursor: (pos: { x: number; y: number } | null) => void;

  /** Indica se há execução em andamento (watch log com step in_progress). */
  isExecuting: boolean;

  /** MIA pausada — usuário clicou Pausar; UI ERP fica liberada. */
  isPaused: boolean;
  setPaused: (paused: boolean) => void;

  /** Intent original armazenado quando user pausou — pra retomada com re-entendimento. */
  pausedIntent: MiaPausedIntent | null;
  savePausedIntent: (intent: MiaPausedIntent) => void;
  clearPausedIntent: () => void;

  /** Ações DOM gravadas (estruturadas) pra workflow replay. */
  recordedActions: MiaRecordedAction[];
  recordAction: (action: Omit<MiaRecordedAction, 'id' | 'timestamp'>) => void;
  clearRecordedActions: () => void;
}

// ── Hook ─────────────────────────────────────────────────────

export function useMiaGlassBox(): UseMiaGlassBoxReturn {
  const [miaModeEnabled, setMiaModeEnabledState] = useState<boolean>(loadMiaMode);
  const [paneSize, setPaneSizeState] = useState<number>(loadPaneSize);
  const [autonomyMode, setAutonomyModeState] = useState<MiaAutonomyMode>(loadAutonomy);
  const [currentPageModel, setCurrentPageModel] = useState<MiaPageModel | null>(null);
  const [watchLog, setWatchLog] = useState<MiaWatchLogEntry[]>(loadWatchLog);
  const [currentHighlight, setCurrentHighlight] = useState<MiaHighlightTarget | null>(null);
  const [cursorPosition, setCursorPosition] = useState<{ x: number; y: number } | null>(null);
  const [recordedActions, setRecordedActions] = useState<MiaRecordedAction[]>(loadRecordedActions);
  const [isPaused, setIsPausedState] = useState<boolean>(false);
  const [pausedIntent, setPausedIntentState] = useState<MiaPausedIntent | null>(loadPausedIntent);

  // Persist watchLog em mudanças (last 200, debounced via effect)
  useEffect(() => {
    try { localStorage.setItem(MIA_WATCHLOG_KEY, JSON.stringify(watchLog.slice(-200))); } catch { /* noop — quota */ }
  }, [watchLog]);

  useEffect(() => {
    try { localStorage.setItem(MIA_RECORDED_KEY, JSON.stringify(recordedActions.slice(-100))); } catch { /* noop */ }
  }, [recordedActions]);

  // ── miaModeEnabled persist ─────────────────────────────────

  const setMiaModeEnabled = useCallback((enabled: boolean) => {
    setMiaModeEnabledState(enabled);
    try { localStorage.setItem(MIA_MODE_KEY, enabled ? '1' : '0'); } catch { /* noop */ }
  }, []);

  const toggleMiaMode = useCallback(() => {
    setMiaModeEnabledState(prev => {
      const next = !prev;
      try { localStorage.setItem(MIA_MODE_KEY, next ? '1' : '0'); } catch { /* noop */ }
      return next;
    });
  }, []);

  // ── paneSize persist ───────────────────────────────────────

  const setPaneSize = useCallback((size: number) => {
    const clamped = Math.max(20, Math.min(60, Math.round(size)));
    setPaneSizeState(clamped);
    try { localStorage.setItem(MIA_PANE_SIZE_KEY, String(clamped)); } catch { /* noop */ }
  }, []);

  // ── autonomyMode persist ───────────────────────────────────

  const setAutonomyMode = useCallback((mode: MiaAutonomyMode) => {
    setAutonomyModeState(mode);
    try { localStorage.setItem(MIA_AUTONOMY_KEY, mode); } catch { /* noop */ }
  }, []);

  // ── watch log ──────────────────────────────────────────────

  /**
   * Adiciona entry no watch log. Agrupamento inteligente:
   * - Se entry.step_id existe E há entry anterior com mesmo step_id E status
   *   in_progress, ATUALIZA a entry existente (em vez de adicionar nova).
   *   Resultado: spinner some quando step termina (não duplica visualmente).
   * - Senão, adiciona normal.
   */
  const addWatchLogEntry = useCallback((entry: Omit<MiaWatchLogEntry, 'id' | 'timestamp'>) => {
    const fullEntry: MiaWatchLogEntry = {
      ...entry,
      id: typeof crypto !== 'undefined' && 'randomUUID' in crypto
        ? crypto.randomUUID()
        : `wl-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: new Date().toISOString(),
    };
    setWatchLog(prev => {
      // Heurística pra agrupar: msgs com mesma kind (clicando/preenchendo/etc)
      // e mesmo "alvo" recebem update in-place quando vira success/error.
      // step_id explícito tem prioridade. Sem step_id, usa match por message stem.
      const isFinal = entry.status === 'success' || entry.status === 'error' || entry.status === 'warning';
      if (isFinal) {
        // Procura entry in_progress correspondente (último wins)
        const targetIdx = [...prev].reverse().findIndex(e => {
          if (e.status !== 'in_progress') return false;
          if (entry.step_id && e.step_id === entry.step_id) return true;
          // Sem step_id, match por verbo/kind comum:
          // "🖱 Clicando: X" → "✓ Clicado: X"
          // "⌨ Preenchendo X" → "✓ Preenchido: X"
          // "▼ Selecionando X" → "✓ Selecionado: X"
          // "→ Navegando" → "✓ Navegado"
          const oldMsg = e.message.toLowerCase();
          const newMsg = entry.message.toLowerCase();
          const pairs = [
            ['clicando', 'clicado'], ['clicando', 'click falhou'],
            ['preenchendo', 'preenchido'], ['preenchendo', 'type falhou'],
            ['selecionando', 'selecionado'], ['selecionando', 'select falhou'],
            ['navegando', 'navegado'], ['aguardando', 'apareceu'],
            ['trocando loja', 'loja trocada'],
          ];
          return pairs.some(([open, close]) => oldMsg.includes(open) && newMsg.includes(close));
        });
        if (targetIdx !== -1) {
          // Replace in-place — actual index = length-1 - reversedIdx
          const actualIdx = prev.length - 1 - targetIdx;
          const next = [...prev];
          next[actualIdx] = { ...fullEntry, id: prev[actualIdx].id };  // preserva id pra animation continuity
          // Atualiza snapshot ref sync (in-place pelo id preservado)
          updateWatchLogSnapshotEntry(prev[actualIdx].id, { ...fullEntry, id: prev[actualIdx].id });
          return next;
        }
      }
      const appended = [...prev, fullEntry];
      const capped = appended.length > 200 ? appended.slice(-200) : appended;
      // Push síncrono pro snapshot ref — evita race no finally do useMia
      pushWatchLogSnapshot(fullEntry);
      return capped;
    });
  }, []);

  const clearWatchLog = useCallback(() => {
    setWatchLog([]);
  }, []);

  // Finaliza entries "in_progress" órfãs (stream encerrou sem update)
  // Renomeia pra status final 'info' + sufixo "(parado)" pra parar o spinner.
  // Sem isso, watch log fica girando indefinidamente quando agent termina.
  const finalizeOrphanedEntries = useCallback(() => {
    setWatchLog(prev => prev.map(e =>
      e.status === 'in_progress'
        ? { ...e, status: 'info' as const, message: `${e.message} (concluído)` }
        : e
    ));
  }, []);

  // ── highlight ──────────────────────────────────────────────

  const highlightElement = useCallback((selector: string, label: string) => {
    setCurrentHighlight({ selector, label });
  }, []);

  const clearHighlight = useCallback(() => {
    setCurrentHighlight(null);
  }, []);

  // ── cursor ─────────────────────────────────────────────────

  const moveCursor = useCallback((pos: { x: number; y: number } | null) => {
    setCursorPosition(pos);
  }, []);

  // ── recordedActions ────────────────────────────────────────

  const recordAction = useCallback((action: Omit<MiaRecordedAction, 'id' | 'timestamp'>) => {
    const full: MiaRecordedAction = {
      ...action,
      id: typeof crypto !== 'undefined' && 'randomUUID' in crypto
        ? crypto.randomUUID()
        : `ra-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      timestamp: new Date().toISOString(),
    };
    setRecordedActions(prev => {
      const next = [...prev, full];
      return next.length > 100 ? next.slice(-100) : next; // cap 100
    });
  }, []);

  const clearRecordedActions = useCallback(() => {
    setRecordedActions([]);
  }, []);

  // ── pause / resume ─────────────────────────────────────────

  const setPaused = useCallback((paused: boolean) => {
    setIsPausedState(paused);
  }, []);

  const savePausedIntent = useCallback((intent: MiaPausedIntent) => {
    setPausedIntentState(intent);
    try { localStorage.setItem(MIA_PAUSED_INTENT_KEY, JSON.stringify(intent)); } catch { /* noop */ }
  }, []);

  const clearPausedIntent = useCallback(() => {
    setPausedIntentState(null);
    try { localStorage.removeItem(MIA_PAUSED_INTENT_KEY); } catch { /* noop */ }
  }, []);

  // ── derived ────────────────────────────────────────────────
  // isExecuting baseado SÓ no último entry — antes era .some() que ficava
  // stuck em true porque entries antigos "in_progress" não eram atualizados
  // (cada ação add 2 entries: 1 in_progress + 1 success, ambos persistem).
  const isExecuting = watchLog.length > 0
    && watchLog[watchLog.length - 1].status === 'in_progress';

  // Snapshot ref pra useMia (hook separado) capturar quando finaliza message.
  // Sync (não async) pra estar atualizado quando useMia salvar message.
  useEffect(() => {
    setWatchLogSnapshot(watchLog);
  }, [watchLog]);

  return {
    miaModeEnabled,
    toggleMiaMode,
    setMiaModeEnabled,
    paneSize,
    setPaneSize,
    autonomyMode,
    setAutonomyMode,
    currentPageModel,
    setCurrentPageModel,
    watchLog,
    addWatchLogEntry,
    clearWatchLog,
    finalizeOrphanedEntries,
    currentHighlight,
    highlightElement,
    clearHighlight,
    cursorPosition,
    moveCursor,
    isExecuting,
    recordedActions,
    recordAction,
    clearRecordedActions,
    isPaused,
    setPaused,
    pausedIntent,
    savePausedIntent,
    clearPausedIntent,
  };
}

